using FromZero;
using System.Text.Json;
static class PreparationExperienceChecks
{
 public static async Task Run(string root,Action<bool,string> check)
 {
  bool Reject(Action action){try{action();return false;}catch(Exception ex)when(ex is InvalidDataException or InvalidOperationException or ArgumentException){return true;}}
  var profiles=PreparationExperience.Profiles.Select(p=>PreparationExperience.Profile(p.Id)).ToList();check(profiles.Count==5&&profiles.Select(p=>p.Profile).Distinct().Count()==5,"Five preparation profiles have stable distinct identities");
  check(profiles.All(p=>!p.GamingLibraries&&!p.CoreLibraries)&&profiles.Single(p=>p.Profile=="streaming").Apps.Contains("obs")&&profiles.Single(p=>p.Profile=="developer").Apps.Contains("node-lts"),"Fresh profiles keep runtime selection explicit while preserving profile apps");
  check(profiles.All(p=>p.PowerPreference=="none"&&p.GraphicsPreference=="none"),"Profiles do not silently enable power or graphics writes");
  var options=PreparationExperience.ChooseGame(new(),"cs2",true);options=PreparationExperience.ChooseGame(options,"cs2",true);check(options.Games.SequenceEqual(new[]{"cs2"})&&options.Apps.Count(a=>a=="steam")==1&&!options.GamingLibraries,"Selecting a Steam game adds its launcher once without selecting every legacy runtime");
  options=PreparationExperience.ChooseGame(options,"valorant",true);check(options.Games.Count==2&&!options.Apps.Contains("riot"),"Games without compiled launcher installers are checked without fabricating install support");
  check(Reject(()=>PreparationPolicy.ValidateOptions(options with{Games=["inject"]}))&&Reject(()=>PreparationPolicy.ValidateOptions(options with{GraphicsPreference="overclock"}))&&Reject(()=>PreparationPolicy.ValidateOptions(options with{PowerPreference="shell"})),"Game and performance choices reject arbitrary instructions");
  check(PreparationExperience.Apps.Count==21&&PreparationExperience.Apps.Select(a=>a.Id).Distinct().Count()==21,"Automatic preparation has 21 distinct curated apps rather than catalog-count padding");
  foreach(var app in PreparationExperience.Apps){var id=PreparationPackages.RecipeId(app.Id);var definition=PreparationPackages.Definition(id);check(PreparationPolicy.PackageIds.Contains(id)&&definition.Arguments.Length>0&&definition.Patterns.Length>0&&definition.ProcessName.Length>0&&!definition.Interactive,"Compiled installer, process and detection recipe: "+app.Name);}
  var tuned=PreparationPolicy.Create(options with{PowerPreference="balanced",GraphicsPreference="fps"},"test","x");check(tuned.Steps.FindIndex(s=>s.Kind=="baseline")<tuned.Steps.FindIndex(s=>s.Kind=="backup")&&tuned.Steps.FindIndex(s=>s.Kind=="preferences")<tuned.Steps.FindIndex(s=>s.Kind=="verify")&&tuned.Steps.Any(s=>s.Kind=="games"),"Baseline precedes writes and profile/game stages precede final verification");
  var before=Snapshot();var after=before with{Checked=DateTimeOffset.Now,NetworkUp=false,AudioOutputs=[],Devices=[new("GPU","PCI\\GPU","Display",10,["PCI\\VEN_10DE&DEV_1"]),new("New USB","USB\\NEW","USB",28,[])],Drivers=[new("GPU","2.0","NVIDIA","oem2.inf","PCI\\GPU","",true)],Apps=[new("Editor","2.0","Publisher","","","Registry")]};
  var changes=PreparationComparison.Compare(before,after,"Display driver");check(changes.Count(c=>c.Regression)==3&&changes.Any(c=>c.Area=="Sürücü"&&!c.Regression)&&changes.All(c=>c.Step=="Display driver"),"Device, network and audio regressions are distinguished from normal version changes and tied to a stage");
  check(!changes.Any(c=>c.Title=="New USB"&&c.Regression),"New device problems are not falsely labeled as a regression from a healthy baseline");check(PreparationComparison.Compare(before,before,"no changes").Count==0,"Unchanged hardware and application snapshots produce no fabricated differences");
  check(PreparationDiagnostics.HttpsEvidence(200,"text/plain","User-agent: *")&&!PreparationDiagnostics.HttpsEvidence(302,"text/plain","User-agent: *")&&!PreparationDiagnostics.HttpsEvidence(200,"text/html","<html>login</html>"),"HTTPS evidence rejects captive-page HTML and unvalidated redirects");
  check(PreparationComparison.Compare(before with{PowerPlan="old"},before with{PowerPlan="new"},"power").Single().Area=="Güç","Before/after reports record actual power-plan changes");
  check(PreparationComparison.Compare(before,before with{Devices=[]},"rescan").Single().Regression,"A formerly present healthy device disappearing is flagged for review");
  var report=new ReadinessReport(DateTimeOffset.Now,[new("sound","Audio","Sound","manual","User must listen"),new("network","Network","Network","attention","No gateway"),new("none","Bluetooth","Bluetooth","not-applicable","Absent")]);check(report.Passed==0&&report.Attention==1&&report.Manual==1,"Manual and unavailable evidence never counts as a passed readiness check");
  var consumer=HardwareRecipes.Build("HP","Victus by HP Laptop 16-e0xxx",true,before.Devices);var business=HardwareRecipes.Build("HP","EliteBook 840 G9",true,before.Devices);check(!consumer.Items[0].Choice.Contains("Image Assistant")&&business.Items[0].Choice.Contains("Image Assistant"),"HP brand alone cannot enable a business-only driver recipe on a consumer laptop");
  check(consumer.Items.Any(i=>i.Basis.Contains("PCI\\VEN_10DE"))&&consumer.Kind.Contains("Dizüstü"),"Hardware recipes retain actual full hardware identity evidence and chassis type");
  var old=PreparationPolicy.Create(new(){Apps=["firefox"]},"sid","x") with{Schema=1};old.Consented=DateTimeOffset.Now;old.Steps.Single(s=>s.Id=="app-firefox").State="done";var upgraded=PreparationPolicy.Upgrade(old);PreparationPolicy.Validate(upgraded,"sid");check(upgraded.Schema==2&&upgraded.Consented==null&&upgraded.State=="planned"&&upgraded.Steps.Single(s=>s.Id=="app-firefox").State=="done","Old plans require a new review before added actions while preserving finished app steps");
  check(Reject(()=>PreparationPolicy.Validate(PreparationPolicy.Upgrade(old with{Machine="other-computer"}),"sid")),"Schema migration cannot turn another computer's state into a valid local plan");
  check(PreparationPackages.Present("app-powertoys",[new("PowerToys (Preview)","0.100","Microsoft","","","Registry")])&&!PreparationPackages.Present("app-powershell",[new("PowerShell 7-preview-x64","7.6","Microsoft","","","Registry")]),"Product naming preserves the PowerToys label while excluding PowerShell preview from stable detection");
  var hold=PreparationPolicy.Create(new(),"sid","x");hold.Consented=DateTimeOffset.Now;var backend=new HoldBackend();await new PreparationEngine(backend,_=>{},()=>false).RunAsync(hold,DateTimeOffset.Now.AddHours(-1),new Progress<string>());check(hold.State=="attention"&&backend.Calls.Last()=="drivers"&&!backend.Calls.Contains("windows"),"A health regression pauses the queue before unrelated later writes");
  var job=PreparationPolicy.Create(new(){PowerPreference="balanced"},"sid","x");var power=new FakePower();var initial=power.Active;await PreparationRecovery.ApplyPowerAsync(job,power);check(power.Active==PreparationRecovery.PowerId("balanced")&&PreparationRecovery.Read<PreparationPowerBackup>(job,"power-backup")?.Original==initial,"Power preference writes a durable original-state backup before changing the plan");await PreparationRecovery.RestorePowerAsync(job,power);check(power.Active==initial&&PreparationRecovery.Read<PreparationPowerBackup>(job,"power-backup")==null,"Power recovery restores and verifies the original state with a simulated backend");
  await PreparationRecovery.ApplyPowerAsync(job,power);power.Active=Guid.NewGuid().ToString();var external=power.Active;await PreparationRecovery.RestorePowerAsync(job,power);check(power.Active==external&&PreparationRecovery.Read<PreparationPowerBackup>(job,"power-backup")!=null,"Recovery preserves later external power changes rather than overwriting them");
  var batteryJob=PreparationPolicy.Create(new(){PowerPreference="performance"},"sid","x");var battery=new FakePower{Ac=false};try{await PreparationRecovery.ApplyPowerAsync(batteryJob,battery);check(false,"Battery guard");}catch(InvalidOperationException){check(battery.Writes==0,"High performance never writes a power preference while running on battery");}
  var unavailable=new FakePower{Available=false};try{await PreparationRecovery.ApplyPowerAsync(batteryJob,unavailable);check(false,"Unavailable plan guard");}catch(InvalidOperationException){check(unavailable.Writes==0,"Unsupported OEM power plans are not silently created or substituted");}
  var source=ApplicationSources.Github.Single(s=>s.Id=="git");var parsed=ApplicationCatalog.GithubHtmlPackage(source,"v2.50.0.windows.1","<a href=\"/git-for-windows/git/releases/download/v2.50.0.windows.1/Git-2.50.0-64-bit.exe\">installer</a>");check(parsed.Version=="v2.50.0.1"&&parsed.Extension==".exe","Official GitHub stable release page parses the pinned x64 installer and version");check(Reject(()=>ApplicationCatalog.GithubHtmlPackage(source,"v2.50.0.windows.1","<a href=\"/attacker/git/releases/download/v2.50.0.windows.1/Git-2.50.0-64-bit.exe\">bad</a>")),"HTML metadata cannot substitute another publisher repository");
  var recipe=new DownloadRecipe("Git 2.50.0",parsed.Url,source.Publisher,["evil.example"],Id:"app-git",Extension:".exe");var offline=new OfflinePreparationPackage("app-git","Packages/git.exe",new string('A',64),1024,"2.50.0",recipe);var pinned=PreparationPackages.RegisterOffline(offline);check(pinned.Hosts.SequenceEqual(new[]{"github.com","githubusercontent.com"})&&pinned.ExpectedSha256==offline.Sha256,"USB import pins compiled hosts, publisher and manifest hash rather than trusting USB rules");check(Reject(()=>PreparationPackages.RegisterOffline(offline with{Recipe=recipe with{Publisher="Other"}}))&&Reject(()=>PreparationPackages.RegisterOffline(offline with{Recipe=recipe with{Url="https://github.com/attacker/git/releases/download/v1/Git-2.50.0-64-bit.exe"}})),"Offline setup refuses publisher and repository tampering before copying an installer");
  var file=Path.Combine(root,"readiness-roundtrip.json");await File.WriteAllTextAsync(file,JsonSerializer.Serialize(before,LocalStore.Json));var roundtrip=JsonSerializer.Deserialize<PreparationSnapshot>(await File.ReadAllTextAsync(file),LocalStore.Json)!;check(roundtrip.Devices[0].Id==before.Devices[0].Id&&roundtrip.Displays.Count==0,"Snapshot evidence survives a JSON round trip for cross-reboot comparisons");
 }
 private static PreparationSnapshot Snapshot()=>new(DateTimeOffset.Now,[new("GPU","PCI\\GPU","Display",0,["PCI\\VEN_10DE&DEV_1"])],[new("GPU","1.0","NVIDIA","oem1.inf","PCI\\GPU","",true)],[new("Editor","1.0","Publisher","","","Registry")],true,["Speakers"],[],[],"HP","Victus",true,[]);
 private sealed class HoldBackend:IPreparationBackend{public List<string> Calls=[];public Task<PreparationOutcome> ExecuteAsync(PreparationJob job,PreparationStep step,IProgress<string> progress,CancellationToken token){Calls.Add(step.Id);return Task.FromResult(new PreparationOutcome(step.Kind=="drivers"?"attention":"done","Checked",Hold:step.Kind=="drivers"));}}
 private sealed class FakePower:IPreparationPower{public string Active=Guid.NewGuid().ToString();public bool Ac=true,Available=true;public int Writes;public string Current()=>Active;public bool PluggedIn()=>Ac;public Task<bool> AvailableAsync(string id)=>Task.FromResult(Available);public Task SetAsync(string id){Active=id;Writes++;return Task.CompletedTask;}}
}
